INSERT INTO notes (date,area,severity,title,body,metric) VALUES ('2026-10-15','cash','do-now','Two progress claims not lodged for September','Parkes solar farm reveg and the bypass batter work both reached their September milestones and neither claim has gone in. Most head contracts close the month on the 25th, so these now slip a full cycle unless they go in this week.','$86,400 of claimable work sitting on the shelf'),('2026-10-15','weather','watch','Rain forecast Thu to Sat across the Central West','Hydromulch on the landfill cap is booked for Thursday. 18mm forecast. Worth moving the crew to the soft fall jobs and re-booking the cap for Monday.','3 days at risk on 2 sites'),('2026-10-15','plant','watch','Hydromulcher 3 is 40 hours off its service','At this week''s run rate it hits the service hours on Tuesday, mid-job on the mine rehab.','40 hrs left'),('2026-10-15','cash','good','Debtor days down for the fifth week running','47 days, from 58 in August. The Monday claims check is working.','47 days vs 58');
INSERT INTO todos (title,detail,source,priority) VALUES ('Lodge September claim, Parkes solar farm reveg','Milestone 3 reached 28 Sep, $54,200','routine',1),('Lodge September claim, bypass batter stabilisation','Milestone reached 30 Sep, $32,200','routine',1),('Chase retention release, council landfill cap','Practical completion was 14 months ago, $18,900 held','routine',1),('Follow up tender T-2291, mine rehab stage 2','Submitted 22 Sep, $312,000, no word','routine',1),('Book Hydromulcher 3 service before Tuesday','40 hours left on the meter','routine',2),('Renew working at heights tickets, 3 crew','Expire 2 Nov','routine',2),('Re-book landfill cap hydromulch for Monday','Rain Thu to Sat','routine',2);
INSERT INTO runs (skill_id,title,status,summary_html,detail_html,run_at) VALUES ('morning-brief','Morning brief','warn','<p><b>Two September progress claims still have not gone in.</b></p><ul><li>$86,400 claimable, both milestones reached</li><li>Rain Thu to Sat, landfill cap job at risk</li><li>9 sites active, 26 quotes and tenders out</li></ul>','<h1 style="font:600 22px Montserrat,system-ui">Morning brief</h1><p style="font:15px/1.6 system-ui;max-width:620px">Parkes solar farm reveg ($54,200) and the bypass batter stabilisation ($32,200) both hit their September milestones and neither claim is lodged. That is the biggest single item on the board.</p><p style="font:15px/1.6 system-ui;max-width:620px">18mm forecast Thursday to Saturday. The landfill cap hydromulch is booked for Thursday: move that crew to the two soft fall jobs and re-book the cap for Monday.</p><p style="font:15px/1.6 system-ui;max-width:620px">Cash is $286,400. Debtor days 47, down from 58 in August.</p>','2026-10-15T06:52:00+11:00'),('cash-and-debtors','Claims and debtors','ok','<p><b>Debtors improving, retentions are the slow money.</b></p><ul><li>$104,300 held in retentions across 6 contracts</li><li>One release overdue by 2 months</li><li>Debtor days 47, down from 58</li></ul>','<h1 style="font:600 22px Montserrat,system-ui">Claims and debtors</h1><p style="font:15px/1.6 system-ui;max-width:620px">Receivables $391,200 across 23 invoices and claims. $104,300 is retention money, and the council landfill cap release ($18,900) is two months past its defects period. Worth a letter, not a phone call.</p>','2026-10-15T06:52:00+11:00'),('jobs-and-quotes','Quotes and tenders','warn','<p><b>Mine rehab tender has gone quiet for three weeks.</b></p><ul><li>$1.46m quoted and tendered out</li><li>Win rate 36% over 90 days, up from 31%</li><li>Four quotes past 14 days with no follow-up</li></ul>','<h1 style="font:600 22px Montserrat,system-ui">Quotes and tenders</h1><p style="font:15px/1.6 system-ui;max-width:620px">$1.46m out across 26 quotes and tenders. The stage 2 mine rehab tender ($312,000) was submitted 22 Sep with no response. Four smaller quotes are past two weeks with no follow-up.</p>','2026-10-15T06:52:00+11:00');
INSERT OR REPLACE INTO pages (slug,title,html,nav,sort,updated_at) VALUES ('plant','Plant','<html><body style="font:15px/1.6 Montserrat,system-ui;padding:26px;color:#1f2a1c"><h1 style="font-size:21px;margin-bottom:4px;color:#589126">Plant and trucks</h1><p style="color:#777;font-size:13px;margin-bottom:20px">Sample data. Hours from the service log, updated weekly.</p><table style="border-collapse:collapse;width:100%;max-width:720px"><tr><th style="padding:7px 8px;text-align:left;border-bottom:2px solid #1f2a1c">Unit</th><th style="padding:7px 8px;text-align:left;border-bottom:2px solid #1f2a1c">Hours now</th><th style="padding:7px 8px;text-align:left;border-bottom:2px solid #1f2a1c">Service due at</th><th style="padding:7px 8px;text-align:left;border-bottom:2px solid #1f2a1c">Left</th><th style="padding:7px 8px;text-align:left;border-bottom:2px solid #1f2a1c">Status</th></tr><tr><td style="padding:7px 8px;border-bottom:1px solid #e3e6dc">Hydromulcher 1</td><td style="padding:7px 8px;border-bottom:1px solid #e3e6dc">2,914</td><td style="padding:7px 8px;border-bottom:1px solid #e3e6dc">3,250</td><td style="padding:7px 8px;border-bottom:1px solid #e3e6dc">336</td><td style="padding:7px 8px;border-bottom:1px solid #e3e6dc">OK</td></tr><tr><td style="padding:7px 8px;border-bottom:1px solid #e3e6dc">Hydromulcher 2</td><td style="padding:7px 8px;border-bottom:1px solid #e3e6dc">1,488</td><td style="padding:7px 8px;border-bottom:1px solid #e3e6dc">1,500</td><td style="padding:7px 8px;border-bottom:1px solid #e3e6dc">12</td><td style="padding:7px 8px;border-bottom:1px solid #e3e6dc"><b style="color:#bd1622">Book now</b></td></tr><tr><td style="padding:7px 8px;border-bottom:1px solid #e3e6dc">Hydromulcher 3</td><td style="padding:7px 8px;border-bottom:1px solid #e3e6dc">3,960</td><td style="padding:7px 8px;border-bottom:1px solid #e3e6dc">4,000</td><td style="padding:7px 8px;border-bottom:1px solid #e3e6dc">40</td><td style="padding:7px 8px;border-bottom:1px solid #e3e6dc"><b style="color:#b07a00">Due Tue</b></td></tr><tr><td style="padding:7px 8px;border-bottom:1px solid #e3e6dc">Hydromulcher 4</td><td style="padding:7px 8px;border-bottom:1px solid #e3e6dc">612</td><td style="padding:7px 8px;border-bottom:1px solid #e3e6dc">1,000</td><td style="padding:7px 8px;border-bottom:1px solid #e3e6dc">388</td><td style="padding:7px 8px;border-bottom:1px solid #e3e6dc">OK</td></tr><tr><td style="padding:7px 8px;border-bottom:1px solid #e3e6dc">Rock slinger truck</td><td style="padding:7px 8px;border-bottom:1px solid #e3e6dc">rego 03 Dec</td><td style="padding:7px 8px;border-bottom:1px solid #e3e6dc"></td><td style="padding:7px 8px;border-bottom:1px solid #e3e6dc">49 days</td><td style="padding:7px 8px;border-bottom:1px solid #e3e6dc">OK</td></tr><tr><td style="padding:7px 8px;border-bottom:1px solid #e3e6dc">Blower truck</td><td style="padding:7px 8px;border-bottom:1px solid #e3e6dc">rego 19 Oct</td><td style="padding:7px 8px;border-bottom:1px solid #e3e6dc"></td><td style="padding:7px 8px;border-bottom:1px solid #e3e6dc">4 days</td><td style="padding:7px 8px;border-bottom:1px solid #e3e6dc"><b style="color:#bd1622">Renew</b></td></tr></table></body></html>',1,10,'2026-10-15');
INSERT OR REPLACE INTO pages (slug,title,html,nav,sort,updated_at) VALUES ('compliance','Compliance','<html><body style="font:15px/1.6 Montserrat,system-ui;padding:26px;color:#1f2a1c"><h1 style="font-size:21px;margin-bottom:4px;color:#589126">Tickets, insurance and certs</h1><p style="color:#777;font-size:13px;margin-bottom:20px">Sample data. Anything inside 30 days is flagged.</p><table style="border-collapse:collapse;width:100%;max-width:720px"><tr><th style="padding:7px 8px;text-align:left;border-bottom:2px solid #1f2a1c">Item</th><th style="padding:7px 8px;text-align:left;border-bottom:2px solid #1f2a1c">Who / what</th><th style="padding:7px 8px;text-align:left;border-bottom:2px solid #1f2a1c">Expires</th><th style="padding:7px 8px;text-align:left;border-bottom:2px solid #1f2a1c">Status</th></tr><tr><td style="padding:7px 8px;border-bottom:1px solid #e3e6dc">Working at heights</td><td style="padding:7px 8px;border-bottom:1px solid #e3e6dc">3 crew</td><td style="padding:7px 8px;border-bottom:1px solid #e3e6dc">02 Nov</td><td style="padding:7px 8px;border-bottom:1px solid #e3e6dc"><b style="color:#b07a00">18 days</b></td></tr><tr><td style="padding:7px 8px;border-bottom:1px solid #e3e6dc">White card</td><td style="padding:7px 8px;border-bottom:1px solid #e3e6dc">All crew</td><td style="padding:7px 8px;border-bottom:1px solid #e3e6dc">n/a</td><td style="padding:7px 8px;border-bottom:1px solid #e3e6dc">OK</td></tr><tr><td style="padding:7px 8px;border-bottom:1px solid #e3e6dc">Public liability $20m</td><td style="padding:7px 8px;border-bottom:1px solid #e3e6dc">Company</td><td style="padding:7px 8px;border-bottom:1px solid #e3e6dc">30 Jun 2027</td><td style="padding:7px 8px;border-bottom:1px solid #e3e6dc">OK</td></tr><tr><td style="padding:7px 8px;border-bottom:1px solid #e3e6dc">ISO 9001 surveillance audit</td><td style="padding:7px 8px;border-bottom:1px solid #e3e6dc">Company</td><td style="padding:7px 8px;border-bottom:1px solid #e3e6dc">Feb 2027</td><td style="